pub use options::{AcornOptions, AcornSourceType, AllowReserved, ECMA_LATEST};

use crate::estree::{Comment, Expression, Program, SourceType, Statement};
use state::{PErr, PResult, Parser};

#[derive(Clone, Debug)]
pub struct Options {
    /// acorn `ecmaVersion`; Svelte uses 16 (ES2025).
    pub ecma_version: u32,
    pub source_type: SourceType,
    /// acorn `preserveParens`: Svelte sets it for template expressions.
    pub preserve_parens: bool,
    /// Svelte's `<script>` hack: exports of names not declared in the script are allowed
    /// (acorn's `undefinedExports` is cleared after every statement).
    pub allow_undefined_exports: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options { ecma_version: 16, source_type: SourceType::Module, preserve_parens: false, allow_undefined_exports: false }
    }
}

impl From<&Options> for AcornOptions {
    fn from(o: &Options) -> AcornOptions {
        AcornOptions {
            ecma_version: o.ecma_version,
            source_type: match o.source_type {
                SourceType::Module => AcornSourceType::Module,
                SourceType::Script => AcornSourceType::Script,
            },
            preserve_parens: o.preserve_parens,
            allow_undefined_exports: o.allow_undefined_exports,
            ..AcornOptions::default()
        }
    }
}

/// acorn's SyntaxError: `message` includes acorn's ` (line:col)` suffix exactly as acorn does
/// (UTF-16 columns); `pos` is the byte offset of the error.
#[derive(Clone, Debug, PartialEq)]
pub struct ParseError {
    pub message: String,
    pub pos: u32,
    pub raised_at: u32,
}

fn finish<T>(r: PResult<T>) -> Result<T, ParseError> {
    r.map_err(|e| match *e {
        PErr::Syntax(e) => e,
        // Only thrown inside template tokens and always caught there.
        PErr::InvalidTemplateEscape => ParseError { message: "Bad escape sequence".into(), pos: 0, raised_at: 0 },
    })
}

/// `acorn.parse(src, opts)`. Comments are appended to `comments` in source order (`onComment`).
pub fn parse(src: &str, opts: &Options, comments: &mut Vec<Comment>) -> Result<Program, ParseError> {
    parse_with(src, &AcornOptions::from(opts), comments)
}

/// `acorn.parse` with the full option set.
pub fn parse_with(src: &str, opts: &AcornOptions, comments: &mut Vec<Comment>) -> Result<Program, ParseError> {
    let mut p = Parser::new(opts, src, 0, comments)?;
    let start = p.start;
    finish(p.next_token().and_then(|_| p.parse_top_level(start)))
}

/// `acorn.parseExpressionAt(src, pos, opts)`: parses one expression starting at byte offset
/// `pos` of the full source (positions stay absolute); the caller reads `end` to continue.
pub fn parse_expression_at(
    src: &str,
    pos: u32,
    opts: &Options,
    comments: &mut Vec<Comment>,
) -> Result<Expression, ParseError> {
    parse_expression_at_with(src, pos, &AcornOptions::from(opts), comments)
}

/// `acorn.parseExpressionAt` with the full option set.
pub fn parse_expression_at_with(
    src: &str,
    pos: u32,
    opts: &AcornOptions,
    comments: &mut Vec<Comment>,
) -> Result<Expression, ParseError> {
    let mut p = Parser::new(opts, src, pos, comments)?;
    finish(p.next_token().and_then(|_| p.parse_expression(expression::ForInit::No, None)))
}

/// Svelte's `parse_statement_at`: one statement starting at `pos`.
pub fn parse_statement_at(
    src: &str,
    pos: u32,
    opts: &Options,
    comments: &mut Vec<Comment>,
) -> Result<Statement, ParseError> {
    let mut p = Parser::new(&AcornOptions::from(opts), src, pos, comments)?;
    let mut exports = statement::Exports::new();
    finish(p.next_token().and_then(|_| p.parse_statement(None, true, Some(&mut exports))))
}

/// acorn `isIdentifierStart(code, astral=true)`.
pub fn is_identifier_start(c: char) -> bool {
    identifier::is_identifier_start(c as u32, true)
}

/// acorn `isIdentifierChar(code, astral=true)`.
pub fn is_identifier_char(c: char) -> bool {
    identifier::is_identifier_char(c as u32, true)
}

